'use strict';

/**
 * Retired design-doc seed — detection for a file the installer used to ship.
 *
 * From 2026-04-12 until 1.63.0 every `aioson setup` copied a project-level
 * `.aioson/context/design-doc.md` whose body was the framework's OWN code
 * organization (a Node.js CLI: `src/commands/`, `src/lib/{domain}/`, `squad/`,
 * `runner/`, `i18n/messages/`, `src/utils.js`, SQLite tables) and whose
 * header claimed a contract no agent honours any more ("must be loaded by
 * @dev before any implementation", "generated by @discovery-design-doc during
 * the pre-dev gate"). The modular `.aioson/design-docs/` governance replaced
 * it the day after it was born (folder-structure, componentization,
 * code-reuse, naming, file-size — each with selector frontmatter and, for
 * size and coupling, a measured checker), but the monolith stayed in the
 * template as a project-local file: never updated, copied verbatim into
 * every consumer, semantically selected on any task that names files or
 * folders, and accepted by the engine as the slug-less fallback for the
 * FEATURE design-doc artifact.
 *
 * This module tells the seed from a real project design record, so the
 * selector can skip it, the engine can refuse it as an artifact, and `doctor`
 * / `update` can name it in the consumer:
 *
 *   - `verbatim` — byte-equal (after line-ending and trailing-space
 *     normalisation) to a version the template shipped; zero project
 *     information, safe to delete;
 *   - `derived`  — still carries the seed's title, heading or retired
 *     contract lines, but the body was edited; review, never auto-delete;
 *   - `null`     — a project-owned design record (any other content).
 */

const crypto = require('node:crypto');
const fs = require('node:fs/promises');
const path = require('node:path');

const DESIGN_DOC_RELATIVE_PATH = path.join('.aioson', 'context', 'design-doc.md');

// sha256 of the normalised content of every version the template shipped:
// pt-BR (ad7ae86a, 2026-04-12) and English (d389b944, 2026-06-01).
const RETIRED_SEED_HASHES = new Set([
  '9992d1a7d6e1ffbd679c2c1d76882116d8cebeba48233b46075b92132ce7b4c6',
  '41efda59d34aa6730da154f1a6a2d66f4c407c2c8175e277412444cf11c4bbbd'
]);

const SEED_TITLE = 'Design Governance — Code Organization Rules';
const SEED_HEADING = '# Design Doc — Code Organization';

// The contract lines the seed asserted (English and pt-BR). No agent kernel
// honours them: dev loads governance through `context:brief`, and no agent
// writes a project-level design document.
const SEED_CONTRACT_LINES = [
  /must load it before any implementation/i,
  /carregado obrigatoriamente por `?@dev`?/i,
  /generated\/updated by `?@discovery-design-doc`?/i,
  /gerado\/atualizado por `?@discovery-design-doc`?/i
];

function normalizeSeedContent(content) {
  const text = String(content || '');
  const withoutBom = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  return withoutBom
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map((line) => line.replace(/[ \t]+$/, ''))
    .join('\n')
    .replace(/\n+$/, '') + '\n';
}

function hashSeedContent(content) {
  return crypto.createHash('sha256').update(normalizeSeedContent(content)).digest('hex');
}

function readFrontmatterTitle(content) {
  const match = String(content || '').match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!match) return '';
  const line = match[1].split(/\r?\n/).find((entry) => /^title\s*:/.test(entry));
  if (!line) return '';
  return line.replace(/^title\s*:\s*/, '').trim().replace(/^["']|["']$/g, '');
}

function hasSeedHeading(content) {
  return String(content || '')
    .split(/\r?\n/)
    .some((line) => line.trim() === SEED_HEADING);
}

/**
 * @returns {'verbatim'|'derived'|null}
 */
function classifyDesignDocSeed(content) {
  const text = String(content || '');
  if (!text.trim()) return null;
  if (RETIRED_SEED_HASHES.has(hashSeedContent(text))) return 'verbatim';
  if (readFrontmatterTitle(text) === SEED_TITLE) return 'derived';
  if (hasSeedHeading(text)) return 'derived';
  if (SEED_CONTRACT_LINES.some((pattern) => pattern.test(text))) return 'derived';
  return null;
}

function isRetiredDesignDocSeed(content) {
  return classifyDesignDocSeed(content) !== null;
}

/**
 * Classifies the file at `filePath`. A missing or unreadable file is `null`
 * (nothing to refuse); callers that need existence check it themselves.
 */
async function classifyDesignDocSeedFile(filePath) {
  let content;
  try {
    content = await fs.readFile(filePath, 'utf8');
  } catch {
    return null;
  }
  return classifyDesignDocSeed(content);
}

/**
 * True when `filePath` is a slug-less `design-doc.md` that exists and is NOT
 * the retired seed — i.e. it may stand in for a feature design document.
 * Slugged files (`design-doc-{slug}.md`) are never the seed and pass on
 * existence alone.
 */
async function isUsableDesignDocFile(filePath) {
  let content;
  try {
    content = await fs.readFile(filePath, 'utf8');
  } catch {
    return false;
  }
  if (path.basename(filePath) !== 'design-doc.md') return true;
  return classifyDesignDocSeed(content) === null;
}

/**
 * Inspects the project's `.aioson/context/design-doc.md`.
 * @returns {{ path: string, exists: boolean, kind: 'verbatim'|'derived'|null }}
 */
async function inspectDesignDocSeed(targetDir) {
  const relPath = DESIGN_DOC_RELATIVE_PATH.split(path.sep).join('/');
  const absPath = path.join(targetDir, DESIGN_DOC_RELATIVE_PATH);
  let content;
  try {
    content = await fs.readFile(absPath, 'utf8');
  } catch {
    return { path: relPath, exists: false, kind: null };
  }
  return { path: relPath, exists: true, kind: classifyDesignDocSeed(content) };
}

module.exports = {
  DESIGN_DOC_RELATIVE_PATH,
  SEED_TITLE,
  SEED_HEADING,
  normalizeSeedContent,
  hashSeedContent,
  classifyDesignDocSeed,
  isRetiredDesignDocSeed,
  classifyDesignDocSeedFile,
  isUsableDesignDocFile,
  inspectDesignDocSeed
};
